```verilog
`timescale 1ns/1ps

module tb;

    // Inputs
    reg clk;
    reg reset;
    reg data;

    // Outputs
    wire start_shifting;

    // Error counter
    integer errors = 0;

    // Instantiate the Unit Under Test (UUT)
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to apply a single bit and check expected output on the positive edge
    task apply_bit(input bit val, input bit expected_out);
        begin
            @(posedge clk);
            #1; // small delay to allow output to settle after clock edge
            data = val;
            @(posedge clk);
            #1;
            if (start_shifting !== expected_out) begin
                $display("Time %0t: Mismatch! data=%b, expected start_shifting=%b, got=%b", 
                         $time, val, expected_out, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Apply reset
        #12;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset error! start_shifting should be 0", $time);
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        @(posedge clk);

        // Test 1: Stream incorrect sequence first (1001), should not trigger
        // Then stream correct sequence "1101"
        // Bits: 1, 0, 0, 1 (reset state), then 1, 1, 0, 1
        $display("Applying test sequence: 1, 0, 0, 1, 1, 1, 0, 1");

        apply_bit(1'b1, 1'b0); // State -> S_1
        apply_bit(1'b0, 1'b0); // State -> S_IDLE
        apply_bit(1'b0, 1'b0); // State -> S_IDLE
        apply_bit(1'b1, 1'b0); // State -> S_1
        apply_bit(1'b1, 1'b0); // State -> S_11
        apply_bit(1'b0, 1'b0); // State -> S_110
        apply_bit(1'b1, 1'b1); // State -> S_DONE, start_shifting becomes 1

        // Test 2: Verify that start_shifting stays high forever once found, even with garbage input
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b1, 1'b1);

        // Test 3: Synchronous reset check
        $display("Applying synchronous reset");
        @(posedge clk);
        reset = 1;
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Synchronous reset failed to clear start_shifting", $time);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: start_shifting not 0 after reset release", $time);
            errors = errors + 1;
        end

        // Test 4: Overlapping sequence check (e.g. 11101 -> wait, 11-1-0-1 or 11101)
        // Let's test sequence: 1, 1, 1, 0, 1
        // State transitions: S_IDLE -> S_1 (1) -> S_11 (1) -> S_11 (1) -> S_110 (0) -> S_DONE (1)
        $display("Applying overlapping sequence: 1, 1, 1, 0, 1");
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b1, 1'b1);

        // Final result reporting
        #20;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
